from topics_a import t, T
C='conveyancer'
t('conveyancer',C,'a conveyancer',"A conveyancer handles the legal side of buying, selling or remortgaging property: checking title, raising enquiries, ordering searches, exchanging contracts, completing and registering the transfer.",["Instruct early to avoid delays.","Check your lender's panel.","Always verify bank details by phone."])
t('licensed-conveyancer',C,'a licensed conveyancer',"Licensed conveyancers are property law specialists regulated by the Council for Licensed Conveyancers, qualified to handle purchases, sales and remortgages.",["Check the CLC register.","Licensed conveyancers focus on property.","They hold client money under strict rules."])
t('residential-conveyancer',C,'a residential conveyancer',"Residential conveyancers handle home purchases, sales, remortgages and transfers of equity.",["Ask about experience with your property type.","Searches reveal local issues.","Track milestones together."])
t('commercial-conveyancer',C,'a commercial conveyancer',"Commercial conveyancers deal with the purchase, sale and leasing of shops, offices, industrial units and investment property.",["VAT on commercial property can apply.","Lease terms need careful review.","Due diligence is wider than residential."])
t('commercial-conveyancer-solicitor',C,'a commercial conveyancing solicitor',"Commercial conveyancing solicitors combine property transactions with advice on business leases, finance and corporate structures.",["Ask about lender requirements.","Environmental searches matter.","Plan completion with the business."])
t('auction-conveyancer',C,'an auction conveyancer',"Auction conveyancers review legal packs before you bid and complete within the auction's fixed timescale, often 28 days.",["Read the legal pack before bidding.","Exchange happens at the fall of the hammer.","Arrange finance in advance."])
t('cash-buyer-conveyancer',C,'a conveyancer for cash buyers',"Cash purchases avoid lender requirements and can move faster, but still need full searches and source-of-funds checks.",["Searches are still important without a lender.","Source-of-funds checks are required.","Cash buyers can push for quicker timelines."])
t('freehold-conveyancer',C,'a freehold conveyancer',"Freehold conveyancers deal with houses where you own the building and land outright, checking title, boundaries and rights of way.",["Check for restrictive covenants.","Boundaries may need clarification.","Estate rentcharges sometimes apply."])
t('leasehold-conveyancer',C,'a leasehold conveyancer',"Leasehold conveyancers review leases, service charges, ground rent and management information for flats and some houses.",["Check the lease length remaining.","Service charges and major works matter.","Management packs can cause delays."])
t('lease-extension-conveyancer',C,'a lease extension conveyancer',"Lease extension specialists help leaseholders extend their lease, usually under statutory rights, alongside a valuer.",["Short leases can affect value and mortgages.","Statutory routes follow set procedures.","Recent reforms are changing the rules."])
t('new-build-conveyancer',C,'a new-build conveyancer',"New-build conveyancers manage developer deadlines, plans, warranties and estate charges for newly built homes.",["Developers often set strict exchange deadlines.","Check the new home warranty.","Estate management charges may apply."])
t('shared-ownership-conveyancer',C,'a shared ownership conveyancer',"Shared ownership conveyancers work with housing association leases, staircasing and lender requirements.",["Shared ownership leases have specific terms.","Housing associations must approve sales.","Staircasing transactions need conveyancing too."])
t('remortgage-conveyancer',C,'a remortgage conveyancer',"Remortgage conveyancers redeem your existing mortgage and register the new lender's charge.",["Some lenders offer free legal packages.","Transfers of equity need extra work.","Start well before your deal ends."])
t('purchase-only-conveyancer',C,'a purchase conveyancer',"Purchase conveyancers act for buyers, checking title, searches and contracts and handling the mortgage and completion.",["Raise questions early.","Read the survey alongside searches.","Stamp Duty is filed by your conveyancer."])
t('sale-only-conveyancer',C,'a sale conveyancer',"Sale conveyancers act for sellers, preparing the contract pack, answering enquiries and redeeming your mortgage.",["Complete property forms promptly.","Gather certificates for works.","Have ID ready."])
# wills & probate
W='wills'
t('will-writing',W,'will writing',"Will writing services prepare a legally valid will setting out who inherits your estate, who acts as executor and, if needed, guardians for children.",["Wills must be properly signed and witnessed.","Marriage usually revokes an earlier will in England and Wales.","Review after big life events."])
t('simple-will',W,'a simple will',"A simple will suits straightforward estates, leaving assets to a partner, children or chosen people without complex trusts.",["Even simple estates benefit from a will.","Name substitute beneficiaries.","Keep the original safe."])
t('complex-will',W,'a complex will',"Complex wills cover blended families, business assets, overseas property, trusts and tax planning.",["Specialist advice reduces disputes.","Trusts can protect beneficiaries.","Overseas assets may need local wills."])
t('mirror-will',W,'mirror wills',"Mirror wills are two separate wills, usually for couples, with almost identical terms leaving everything to each other and then to the same beneficiaries.",["Either person can change their will later.","Consider protection for children.","Mutual wills are different and rare."])
t('living-will',W,'a living will',"A living will, or advance decision, sets out medical treatments you would refuse in future if you lose capacity; a health and welfare lasting power of attorney is a separate option.",["Advance decisions to refuse life-sustaining treatment must meet strict rules.","Share it with your GP.","Consider an LPA as well."])
t('business-will',W,'a business will',"Business wills deal with company shares, partnership interests and business property, often alongside shareholder agreements and business relief.",["Check articles and partnership agreements.","Business relief rules are changing.","Consider separate business wills."])
t('discretionary-trust-will',W,'a will with a discretionary trust',"A discretionary trust will lets trustees decide how assets are used among a group of beneficiaries, giving flexibility and protection.",["Useful for vulnerable beneficiaries.","Trusts have tax rules.","Leave a letter of wishes."])
t('property-trust-will',W,'a property trust will',"A property trust will places your share of a jointly owned home into trust, often to protect it for children while allowing a partner to live there.",["Requires tenants in common ownership.","Can protect against remarriage risks.","Trustees need clear guidance."])
t('family-trust',W,'a family trust',"Family trusts hold assets for family members, managed by trustees, for purposes such as protecting wealth or planning for inheritance tax.",["Trusts usually need registering with HMRC.","Different trusts have different tax treatment.","Choose trustees carefully."])
t('estate-planning',W,'estate planning',"Estate planning brings together wills, trusts, gifts, pensions and powers of attorney so your wishes are followed and tax is managed.",["Start with clear goals.","Review regularly.","Coordinate with financial advice."])
t('estate-planning-advisor',W,'an estate planning adviser',"Estate planning advisers help families organise assets and plans for later life and inheritance, often with solicitors and financial advisers.",["Check whether advice is regulated.","Pensions often pass outside the will.","Gifts need records."])
t('estate-administration',W,'estate administration',"Estate administration is the work of collecting a deceased person's assets, paying debts and taxes and distributing what remains.",["Executors can be personally liable for mistakes.","Keep clear accounts.","Professional help suits complex estates."])
t('executor-assistance',W,'help for executors',"Executors often need help with probate, valuations, tax and dealing with banks and property; professionals can take on some or all of the work.",["You can choose how much help you need.","Executors can step back before acting.","Keep receipts for expenses."])
t('executor-services',W,'professional executor services',"Professional executors, such as solicitors, act as or assist executors, managing the estate from start to finish.",["Fees should be explained clearly.","Professionals help where families disagree.","Ask about timescales."])
t('probate-application',W,'a probate application',"A probate application asks the court for a grant allowing executors to deal with an estate, usually online, after any inheritance tax forms are filed.",["Most applications are made online.","IHT forms may be needed first.","Processing times vary."])
t('letters-of-administration',W,'letters of administration',"When someone dies without a valid will, the closest relative usually applies for letters of administration to deal with the estate.",["Intestacy rules decide who can apply.","The process is similar to probate.","Unmarried partners have no automatic rights."])
t('contentious-probate',W,'contentious probate',"Contentious probate covers disputes about wills and estates, such as challenges to validity, claims under the Inheritance Act and executor disputes.",["Inheritance Act claims have a six-month time limit from the grant.","Caveats can stop a grant temporarily.","Mediation resolves many disputes."])
t('inheritance-dispute',W,'an inheritance dispute',"Inheritance disputes arise when family members or dependants believe a will is invalid or unfair, or an estate is being mishandled.",["Act quickly because time limits apply.","Gather evidence of capacity and influence.","Costs can be high; consider settlement."])
t('deed-of-variation',W,'a deed of variation',"A deed of variation lets beneficiaries change how an estate passes, within two years of death, often for tax or family reasons.",["All affected beneficiaries must agree.","Statements may be needed for tax effect.","Cannot be made for payment."])
